export function LottieAnimation({
  scene = "{{scene}}",
  duration = {{duration}},
  loop = {{loop}},
  accent = "{{accent}}",
}) {
  const names = { spin: "mot-lot-spin", morph: "mot-lot-morph", bounce: "mot-lot-bounce" };
  const target = scene === "morph" ? "path" : "svg";
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa", textAlign: "center" }}>
      <svg viewBox="0 0 100 100" width="90" height="90" aria-hidden="true" className={target === "svg" ? "scene" : undefined} style={{ margin: "0 auto", display: "block", transformOrigin: "50% 50%" }}>
        <path fill={accent} d="M50 10 L90 90 L10 90 Z" className={target === "path" ? "scene" : undefined} />
      </svg>
      <p style={{ margin: "10px 0 0" }}>Vector scene: {scene} &middot; approximates a Lottie-style JSON animation, played from inline SVG</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .scene { animation: ${names[scene]} ${duration}ms ease-in-out ${loop ? "infinite" : 1}; }
          @keyframes mot-lot-spin { to { transform: rotate(360deg); } }
          @keyframes mot-lot-morph { 0%,100% { d: path("M50 10 L90 90 L10 90 Z"); } 50% { d: path("M50 20 C80 20 80 80 50 80 C20 80 20 20 50 20 Z"); } }
          @keyframes mot-lot-bounce { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-18px); } }
        }
      `}</style>
    </div>
  );
}
